#!/usr/bin/env python3
"""Раздел 1.4: информационная модель (ER) и диаграммы классов.
Основа – docs/kursovaya/src/er-part.docx (текст, таблицы и рисунок ER). Добавляются две диаграммы классов и таблица классов.
Использование: python3 build_14.py выход.docx
"""
import os, sys
import docx
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Builder, replace_in_runs

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
KURS = os.path.join(ROOT, 'docs', 'kursovaya')
d = docx.Document(os.path.join(KURS, 'src', 'er-part.docx'))
P = d.paragraphs
b = Builder(d, P[1], P[4], P[6])
# нумерация: таблицы 1.5 – 1.7 занимают бизнес-правила, заинтересованные лица и функциональные требования раздела 1.3
replace_in_runs(d, 'рисунке 1.12', 'рисунке 1.10'); replace_in_runs(d, 'Рисунок 1.12 –', 'Рисунок 1.10 –')
replace_in_runs(d, 'таблице 1.6', 'таблице 1.8'); replace_in_runs(d, 'Таблица 1.6 –', 'Таблица 1.8 –')
replace_in_runs(d, 'таблице 1.7', 'таблице 1.9'); replace_in_runs(d, 'Таблица 1.7 –', 'Таблица 1.9 –')

# порядок «краткий абзац со ссылкой – рисунок – описание»: высокие рисунки не оставляют пустых мест внизу страниц
b.para('Структура программного средства описывается диаграммами классов, которые показывают классы, их атрибуты и операции и связи между ними. Основные классы предметной области показаны на рисунке 1.11.')
b.figure(os.path.join(KURS, 'class-domain.png'), 'Рисунок 1.11 – Диаграмма классов предметной области')
b.para('На диаграмме использованы ассоциация, агрегация (клиент объединяет счета, вклады и заявки, но они существуют как самостоятельные записи) и композиция (документ состоит из проводок и не существует без них). Каждая связь подписана действием, рядом с концами указаны кратности. Атрибуты классов соответствуют столбцам таблиц базы данных, а операции – функциям сервисов программного средства. Клиент владеет счетами, открывает вклады и подаёт заявки на кредит. Каждая денежная операция (перевод, оплата услуги) оформляется документом, который состоит из проводок двойной записи: проводка списывает сумму с одного счёта и зачисляет на другой. Остаток счёта вычисляется по проводкам, а денежные суммы хранятся целым числом копеек. Назначение классов приведено в таблице 1.10.')
b.table('Таблица 1.10 – Классы модели предметной области', ['Класс', 'Назначение', 'Основные атрибуты', 'Основные операции'], [
    ('Client', 'Клиент банка с анкетными данными', 'id, lastName, firstName, birthDate, kycStatus', 'verifyClient(), rejectClient()'),
    ('Account', 'Счёт клиента в одной валюте с номером IBAN', 'id, iban, currency, balance, status', 'openForUser(), closeForUser()'),
    ('Card', 'Банковская платёжная карта с лимитами', 'id, last4, dailyLimit, status', 'setBlocked(), updateLimits(), purchase()'),
    ('Deposit', 'Вклад клиента, открытый по условиям продукта', 'id, amount, ratePercent, maturityDate, status', 'quoteEarlyClose(), closeEarly()'),
    ('LoanApplication', 'Заявка на кредит с результатом скоринга', 'id, amount, termMonths, pdPercent, status', 'apply(), decide(), sign()'),
    ('Loan', 'Выданный кредит с остатком основного долга', 'id, amount, ratePercent, principalBalance, status', 'repayPartial(), repayFull()'),
    ('Payment', 'Оплата услуги по каталогу получателей', 'id, requisite, amount, fee', 'pay(), getReceipt()'),
    ('TransferIntent', 'Заявка на перевод со статусом и комиссией', 'id, kind, amount, fee, status', 'confirmTransfer(), cancelTransfer()'),
    ('Document', 'Банковский документ, объединяющий проводки одной операции', 'id, type, status, idempotencyKey', 'post(), reverse()'),
    ('Posting', 'Проводка двойной записи: дебет одного счёта и кредит другого', 'id, debitAccount, creditAccount, amount', '–'),
], [3.2, 4.8, 4.6, 3.9])
b.para('Диаграмма классов описывает данные и их поведение, но не показывает, где выполняется бизнес-логика. В программном средстве она вынесена в слой сервисов: контроллеры принимают запрос и вызывают сервис, сервис выполняет операцию в одной транзакции и обращается к моделям с SQL-запросами. Ключевые сервисы показаны на рисунке 1.12.')
b.figure(os.path.join(KURS, 'class-services.png'), 'Рисунок 1.12 – Диаграмма классов слоя бизнес-логики')
b.para('Пунктирная стрелка означает, что один сервис использует другой, подпись указывает действие: закрытие операционного дня запускает начисление процентов по вкладам, исполнение автоплатежей, обработку кредитов и отправку пакета межбанковских платежей; кредит оценивается сервисом скоринга; переводы проверяются антифрод-сервисом; переводы и подписание кредита подтверждаются одноразовым кодом. Сервисы вкладов, платежей, кредитов, карт и переводов проводят деньги через сервис учёта, работают со счетами через сервис счетов, ведут журнал аудита и отправляют уведомления, поэтому такие связи на рисунке не показаны.')
b.para('Информационная модель и диаграммы классов определяют структуру данных программного средства и разделение его бизнес-логики на слои. На их основе разрабатываются архитектура программного средства и алгоритмы выполнения ключевых операций.')
d.save(sys.argv[1])
